    <script>
        // Initialize Lucide Icons
        lucide.createIcons();

        // Cart State
        let cart = [];

        // Loader
        window.addEventListener('load', () => {
            const loader = document.getElementById('loader');
            gsap.to(loader, {
                opacity: 0,
                duration: 0.8,
                delay: 1,
                onComplete: () => {
                    loader.style.display = 'none';
                    initAnimations();
                }
            });
        });

        // GSAP Animations
        function initAnimations() {
            gsap.registerPlugin(ScrollTrigger);

            // Hero Text Animation
            gsap.to('.hero-text', {
                opacity: 1,
                y: 0,
                duration: 1,
                stagger: 0.2,
                ease: 'power3.out'
            });

            // Reveal Animations
            gsap.utils.toArray('.reveal').forEach(element => {
                gsap.to(element, {
                    scrollTrigger: {
                        trigger: element,
                        start: 'top 80%',
                        toggleActions: 'play none none none'
                    },
                    opacity: 1,
                    y: 0,
                    duration: 0.8,
                    ease: 'power3.out'
                });
            });

            // Stagger Children
            gsap.utils.toArray('.stagger-children').forEach(container => {
                gsap.to(container.children, {
                    scrollTrigger: {
                        trigger: container,
                        start: 'top 80%',
                        toggleActions: 'play none none none'
                    },
                    opacity: 1,
                    y: 0,
                    duration: 0.6,
                    stagger: 0.1,
                    ease: 'power3.out'
                });
            });

            // Parallax Effect
            gsap.utils.toArray('.parallax-container').forEach(container => {
                gsap.to(container.querySelector('img'), {
                    scrollTrigger: {
                        trigger: container,
                        start: 'top bottom',
                        end: 'bottom top',
                        scrub: 1
                    },
                    y: -100,
                    ease: 'none'
                });
            });
        }

        // Mobile Menu
        const mobileMenuBtn = document.getElementById('mobileMenuBtn');
        const mobileMenu = document.getElementById('mobileMenu');
        const closeMobileMenu = document.getElementById('closeMobileMenu');
        const mobileLinks = document.querySelectorAll('.mobile-link');

        mobileMenuBtn.addEventListener('click', () => {
            mobileMenu.classList.add('active');
        });

        closeMobileMenu.addEventListener('click', () => {
            mobileMenu.classList.remove('active');
        });

        mobileLinks.forEach(link => {
            link.addEventListener('click', () => {
                mobileMenu.classList.remove('active');
            });
        });

        // Cart Sidebar
        const cartBtn = document.getElementById('cartBtn');
        const cartSidebar = document.getElementById('cartSidebar');
        const closeCart = document.getElementById('closeCart');

        cartBtn.addEventListener('click', () => {
            cartSidebar.classList.add('active');
        });

        closeCart.addEventListener('click', () => {
            cartSidebar.classList.remove('active');
        });

        // Add to Cart
        const addToCartBtns = document.querySelectorAll('.add-to-cart');
        const cartCount = document.getElementById('cartCount');
        const cartItems = document.getElementById('cartItems');
        const cartTotal = document.getElementById('cartTotal');

        addToCartBtns.forEach(btn => {
            btn.addEventListener('click', (e) => {
                e.stopPropagation();
                const name = btn.dataset.name;
                const price = parseFloat(btn.dataset.price);

                const existingItem = cart.find(item => item.name === name);

                if (existingItem) {
                    existingItem.quantity++;
                } else {
                    cart.push({ name, price, quantity: 1 });
                }

                updateCart();
                showSuccess(`${name} adicionado ao carrinho!`);
            });
        });

        function updateCart() {
            const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
            cartCount.textContent = totalItems;

            if (cart.length === 0) {
                cartItems.innerHTML = '<p class="text-gray-500 text-center py-12">Seu carrinho está vazio</p>';
                cartTotal.textContent = 'R$ 0,00';
            } else {
                cartItems.innerHTML = cart.map(item => `
                    <div class="flex justify-between items-center mb-4 pb-4 border-b">
                        <div>
                            <h4 class="font-semibold">${item.name}</h4>
                            <p class="text-sm text-gray-600">Qtd: ${item.quantity}</p>
                        </div>
                        <div class="text-right">
                            <p class="font-bold">R$ ${(item.price * item.quantity).toFixed(2)}</p>
                            <button onclick="removeFromCart('${item.name}')" class="text-sm text-red-500 hover:text-red-700">Remover</button>
                        </div>
                    </div>
                `).join('');

                const total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
                cartTotal.textContent = `R$ ${total.toFixed(2)}`;
            }
        }

        function removeFromCart(name) {
            cart = cart.filter(item => item.name !== name);
            updateCart();
        }

        // Product Filters
        const filterBtns = document.querySelectorAll('.filter-btn');
        const productCards = document.querySelectorAll('.product-card');

        filterBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                filterBtns.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');

                const filter = btn.dataset.filter;

                productCards.forEach(card => {
                    if (filter === 'all' || card.dataset.category === filter) {
                        card.style.display = 'block';
                        gsap.fromTo(card, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.5 });
                    } else {
                        card.style.display = 'none';
                    }
                });
            });
        });

        // Newsletter Form
        const newsletterForm = document.getElementById('newsletterForm');
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            showSuccess('Cadastro realizado com sucesso! Verifique seu e-mail para o cupom de 10% OFF.');
            newsletterForm.reset();
        });

        // Contact Form
        const contactForm = document.getElementById('contactForm');
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();
            showSuccess('Mensagem enviada com sucesso! Entraremos em contato em breve.');
            contactForm.reset();
        });

        // Modal
        function showSuccess(message) {
            document.getElementById('successMessage').textContent = message;
            document.getElementById('successModal').classList.add('active');
        }

        function closeModal() {
            document.getElementById('successModal').classList.remove('active');
        }

        // Smooth Scroll
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                e.preventDefault();
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    target.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            });
        });

        // Navbar Scroll Effect
        let lastScroll = 0;
        const navbar = document.getElementById('navbar');

        window.addEventListener('scroll', () => {
            const currentScroll = window.pageYOffset;

            if (currentScroll > 100) {
                navbar.style.boxShadow = '0 4px 20px rgba(0,0,0,0.1)';
            } else {
                navbar.style.boxShadow = '0 2px 10px rgba(0,0,0,0.05)';
            }

            lastScroll = currentScroll;
        });
    </script>
</body>
</html>
