    <script>
    // Initialize Lucide Icons
    if (typeof lucide !== 'undefined') lucide.createIcons();

    // Cart State
    let cart = [];
    let wishlist = [];

    // Loader
    window.addEventListener('load', () => {
        const loader = document.getElementById('loader');
        if (loader) {
            gsap.to(loader, {
                opacity: 0, duration: 0.8, delay: 1,
                onComplete: () => { loader.style.display = 'none'; initAnimations(); }
            });
        }
    });

    // GSAP Animations
    function initAnimations() {
        if (typeof gsap === 'undefined') return;
        if (typeof ScrollTrigger !== 'undefined') gsap.registerPlugin(ScrollTrigger);

        gsap.to('.hero-text', { opacity: 1, y: 0, duration: 1, stagger: 0.2, ease: 'power3.out' });

        gsap.utils.toArray('.reveal').forEach(element => {
            gsap.to(element, {
                scrollTrigger: { trigger: element, start: 'top 85%', toggleActions: 'play none none none' },
                opacity: 1, y: 0, duration: 0.8, ease: 'power3.out'
            });
        });

        gsap.utils.toArray('.stagger-children').forEach(container => {
            gsap.to(container.children, {
                scrollTrigger: { trigger: container, start: 'top 80%', toggleActions: 'play none none none' },
                opacity: 1, y: 0, duration: 0.6, stagger: 0.1, ease: 'power3.out'
            });
        });
    }

    // Mobile Menu
    const mobileMenu = document.getElementById('mobileMenu');
    const mobileMenuBtn = document.getElementById('mobileMenuBtn');
    const closeMobileMenu = document.getElementById('closeMobileMenu');
    if (mobileMenuBtn && mobileMenu) mobileMenuBtn.addEventListener('click', () => mobileMenu.classList.add('active'));
    if (closeMobileMenu && mobileMenu) closeMobileMenu.addEventListener('click', () => mobileMenu.classList.remove('active'));
    document.querySelectorAll('.mobile-link').forEach(link => {
        link.addEventListener('click', () => { if (mobileMenu) mobileMenu.classList.remove('active'); });
    });

    // Cart Sidebar
    const cartSidebar = document.getElementById('cartSidebar');
    const cartBtn = document.getElementById('cartBtn');
    const closeCart = document.getElementById('closeCart');
    if (cartBtn && cartSidebar) cartBtn.addEventListener('click', () => cartSidebar.classList.add('active'));
    if (closeCart && cartSidebar) closeCart.addEventListener('click', () => cartSidebar.classList.remove('active'));

    // Search Modal
    const searchModal = document.getElementById('searchModal');
    const searchBtn = document.getElementById('searchBtn');
    const closeSearch = document.getElementById('closeSearch');
    if (searchBtn && searchModal) searchBtn.addEventListener('click', () => searchModal.classList.add('active'));
    if (closeSearch && searchModal) closeSearch.addEventListener('click', () => searchModal.classList.remove('active'));

    // Quick View
    const quickviewModal = document.getElementById('quickviewModal');
    const closeQuickview = document.getElementById('closeQuickview');
    if (closeQuickview && quickviewModal) closeQuickview.addEventListener('click', () => quickviewModal.classList.remove('active'));

    // Add to Cart
    document.querySelectorAll('.add-to-cart').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const name = btn.dataset.name;
            const price = parseFloat(btn.dataset.price);
            if (!name || isNaN(price)) return;

            const existingItem = cart.find(item => item.name === name);
            if (existingItem) existingItem.quantity++;
            else cart.push({ name, price, quantity: 1 });

            updateCart();
            showToast(name + ' adicionado ao carrinho!');
        });
    });

    // Update Cart
    function updateCart() {
        const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);
        const cartCountEl = document.getElementById('cartCount');
        const cartItemsEl = document.getElementById('cartItems');
        const cartSubtotalEl = document.getElementById('cartSubtotal');
        const cartShippingEl = document.getElementById('cartShipping');
        const cartTotalEl = document.getElementById('cartTotal');
        const shippingRemainingEl = document.getElementById('shippingRemaining');
        const shippingProgressEl = document.getElementById('shippingProgress');

        if (cartCountEl) cartCountEl.textContent = totalItems;
        if (!cartItemsEl || !cartTotalEl) return;

        const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
        const shipping = subtotal >= 299 ? 0 : 25;
        const total = subtotal + shipping;
        const remaining = Math.max(0, 299 - subtotal);
        const progress = Math.min(100, (subtotal / 299) * 100);

        if (cart.length === 0) {
            cartItemsEl.innerHTML = '<p class="text-gray-500 text-center py-12">Seu carrinho está vazio</p>';
            if (shippingRemainingEl) shippingRemainingEl.textContent = 'R$ 299,00';
            if (shippingProgressEl) shippingProgressEl.style.width = '0%';
        } else {
            cartItemsEl.innerHTML = cart.map(item => `
                <div class="flex justify-between items-center mb-4 pb-4 border-b">
                    <div class="flex-1">
                        <h4 class="font-semibold text-sm">${item.name}</h4>
                        <p class="text-xs text-gray-600">Qtd: ${item.quantity}</p>
                    </div>
                    <div class="text-right">
                        <p class="font-bold text-sm">R$ ${(item.price * item.quantity).toFixed(2)}</p>
                        <button onclick="removeFromCart('${item.name}')" class="text-xs text-red-500 hover:text-red-700">Remover</button>
                    </div>
                </div>
            `).join('');
            if (shippingRemainingEl) shippingRemainingEl.textContent = 'R$ ' + remaining.toFixed(2);
            if (shippingProgressEl) shippingProgressEl.style.width = progress + '%';
        }

        if (cartSubtotalEl) cartSubtotalEl.textContent = 'R$ ' + subtotal.toFixed(2);
        if (cartShippingEl) cartShippingEl.textContent = shipping === 0 ? 'Grátis!' : 'R$ ' + shipping.toFixed(2);
        if (cartTotalEl) cartTotalEl.textContent = 'R$ ' + total.toFixed(2);
    }

    function removeFromCart(name) {
        cart = cart.filter(item => item.name !== name);
        updateCart();
    }

    // Toast Notification
    function showToast(message) {
        const toast = document.getElementById('toast');
        const toastMessage = document.getElementById('toastMessage');
        if (toast && toastMessage) {
            toastMessage.textContent = message;
            toast.classList.add('show');
