        e.target.reset();
    });

    document.getElementById('contactForm').addEventListener('submit', (e) => {
        e.preventDefault();
        showSuccess(currentLang === 'pt' ? 'Mensagem enviada com sucesso!' : 
                    currentLang === 'es' ? '¡Mensaje enviado con éxito!' : 
                    'Message sent successfully!');
        e.target.reset();
    });

    // ============================================
    // MODAL
    // ============================================
    function showSuccess(message) {
        document.getElementById('successMessage').textContent = message;
        document.getElementById('successModal').classList.add('active');
    }
    function closeModal() {
        document.getElementById('successModal').classList.remove('active');
    }

    // ============================================
    // SMOOTH SCROLL
    // ============================================
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            const target = document.querySelector(this.getAttribute('href'));
            if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
    });

    // ============================================
    // NAVBAR SCROLL
    // ============================================
    window.addEventListener('scroll', () => {
        const navbar = document.getElementById('navbar');
        if (window.pageYOffset > 100) navbar.style.boxShadow = '0 4px 20px rgba(0,0,0,0.1)';
        else navbar.style.boxShadow = '0 2px 10px rgba(0,0,0,0.05)';
    });

    // Initialize Lucide Icons
    lucide.createIcons();
